def hook(ctx, nb):
    nb['stage'] = 'search'
    nb['last_hint'] = ''
    return {'skills': [{'text': 'Search, inspect a matching product, select every required option, verify constraints, then buy.'}], 'tool_hint': 'Use visible page evidence before advancing to the next shopping stage.'}

def hook(ctx, nb):
    state = ctx.get('state', {})
    text = str(state).lower()
    if 'buy now' in text and ('required' in text or 'select' in text):
        msg = 'Before buying, select every required option shown on the product page.'
        if nb.get('last_hint') != msg:
            nb['last_hint'] = msg
            return {'message': msg}
    return None
